  .subscription-box {
    max-width: 100%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 1em;
    position: relative;
    border-radius: 5px;
    background-color: transparent;
    overflow: hidden;
  }

  .subscription-box::after {
    background-color: var(--color-accent);
    opacity: 0.2;
    content: "";
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    z-index: -1;
  }

  .subscription-form {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 30rem;
    --color-danger: #fc365e;
    --color-success: #48c774;
  }

  .subscription-form-title {
    margin-top: 0;
    font-size: 1.6rem;
  }

  .subscription-form-explainer {
    text-align: left;
    margin-bottom: 0em;
    margin-top: 0;
    font-size: 1.125em;
  }

  .subscription-form input, .subscription-form button {
    padding: 10px;
    border-radius: 5px;
    box-shadow: none;
    border: 1px solid #fFFFFF;
  }

  .subscription-form input {
    background-color: transparent;
  }

  .subscription-form button {
    text-align: center;
    text-transform: uppercase;
    background-color: var(--color-accent);
    color: #383838;
  }

  .subscription-form .success-message, .subscription-form .error-message {
    display: none;
  }

  .subscription-form.success .success-message, .subscription-form.error .error-message {
    display: flex;
    margin-top: 10px;
    font-weight: 500;
  }

  .subscription-form.success .success-message {
    color: var(--color-success);
  }

  .subscription-form.error .error-message {
    color: var(--color-danger);
  }

  .label-description {
    font-weight: 500;
    margin-left: 50px;
    white-space: nowrap;
  }

  .subscribe-box {
    background-color: #fff;
    display: flex;
    padding: 0.3em;
    border-radius: 3px;
  }

  .subscribe-box input {
    border: none;
    box-shadow: none;
    flex: 2;
    margin: 0;
    padding: 0 1em;
    outline: none;
    font-size: 15px;
  }

  .subscribe-box button {
    flex: 1;
    font-size: .8rem;
    padding: 1em;
    font-weight: 700;
  }

  .switch {
    position: relative;
    display: flex;
    width: 45px;
    height: 25px;
    margin-bottom: 1em;
    margin-right: 1em;
  }

  .switch input {
    opacity: 0;
    width: 0;
    height: 0;
  }

  .slider {
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: #595959;
    -webkit-transition: .4s;
    transition: .4s;
  }

  .slider:before {
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    left: 2px;
    bottom: 2.5px;
    background-color: white;
    -webkit-transition: .4s;
    transition: .4s;
  }

  input:checked + .slider {
    background-color: var(--color-accent);
  }

  input:focus + .slider {
    box-shadow: 0 0 1px #2196F3;
  }

  input:checked + .slider:before {
    -webkit-transform: translateX(20px);
    -ms-transform: translateX(20px);
    transform: translateX(20px);
  }

  .slider.round {
    border-radius: 34px;
  }

  .slider.round:before {
    border-radius: 50%;
  }

    .alert {
    --color-info: #259eef;
    --color-warning: #e3bc1f;
    --color-danger: #fc365e;
    --color-success: #48c774;
    --color-alert: #666;

    --content-info: "i";
    --content-warning: "!";
    --content-danger: "!";
    --content-success: "✓";
    --content-alert: "i";

    border: 2px solid var(--color-alert);
    border-radius: 5px;
    color: var(--color-alert);
    margin-bottom: 2em;
    margin-top: 1em;
    padding: 1em;
    position: relative;
    width: 100%;
    font-weight: 500;
    font-size: 16px;
  }

  .alert:before {
    align-items: center;
    background-color: var(--color-alert);
    border-radius: 50%;
    color: #fff;
    content: var(--content-alert);
    display: flex;
    font-family: monospace;
    font-weight: 700;
    height: 24px;
    justify-content: center;
    left: -12px;
    line-height: 1;
    position: absolute;
    top: -12px;
    width: 24px;
  }

  .alert:after {
    background-color: var(--color-alert);
    content: "";
    height: 100%;
    left: 0;
    opacity: .1;
    position: absolute;
    right: 0;
    top: 0;
    width: 100%;
    z-index: -1;
  }

  .alert.info {
    --color-alert: var(--color-info);
    --content-alert: var(--content-info);
  }

  .alert.warning {
    --color-alert: var(--color-warning);
    --content-alert: var(--content-warning);
  }

  .alert.danger {
    --color-alert: var(--color-danger);
    --content-alert: var(--content-danger);
  }

  .alert.success {
    --color-alert: var(--color-success);
    --content-alert: var(--content-success);
  }




